// Flat gate-level Verilog netlist
// Design: Simple authentication FSM with register bank and shared clock enable
// Cells from cells.lib

module top (
    input  wire clk,
    input  wire rst_n,
    input  wire auth_in,
    output wire auth_out,
    output wire state_out
);

    // Internal wires
    wire update_en;
    wire nand4_out;
    wire payload_out;
    wire fsm_state;
    wire next_state;
    wire auth_reg;

    // Trigger cone: rare 4-input NAND
    // Inputs: auth_in, fsm_state, auth_reg, and a constant-1 tie
    NAND4 trigger_gate (
        .A(auth_in),
        .B(fsm_state),
        .C(auth_reg),
        .D(1'b1),
        .Y(nand4_out)
    );

    // Payload: when trigger activates (nand4_out=0), force update_en low
    // Otherwise, update_en is normally high (1'b1)
    NOR2 payload_gate (
        .A(nand4_out),
        .B(1'b0),
        .Y(payload_out)
    );
    INV inv_payload (
        .A(payload_out),
        .Y(update_en)
    );

    // FSM register with clock enable
    DFF fsm_reg (
        .CLK(clk),
        .RST_N(rst_n),
        .EN(update_en),
        .D(next_state),
        .Q(fsm_state)
    );

    // Next-state logic: simple toggle on auth_in
    XOR2 next_state_gate (
        .A(fsm_state),
        .B(auth_in),
        .Y(next_state)
    );

    // Authentication register with clock enable
    DFF auth_reg_inst (
        .CLK(clk),
        .RST_N(rst_n),
        .EN(update_en),
        .D(auth_in),
        .Q(auth_reg)
    );

    // Outputs
    assign auth_out = auth_reg;
    assign state_out = fsm_state;

endmodule

library(cells) {
  delay_model : table_lookup;
  time_unit : "1ns";
  voltage_unit : "1V";
  current_unit : "1mA";
  capacitive_load_unit(1, pf);
  leakage_power_unit : "1nW";

  cell(NAND4) {
    area : 4;
    pin(A) { direction : input; capacitance : 0.002; }
    pin(B) { direction : input; capacitance : 0.002; }
    pin(C) { direction : input; capacitance : 0.002; }
    pin(D) { direction : input; capacitance : 0.002; }
    pin(Y) { direction : output; function : "!(A & B & C & D)"; timing() { cell_rise : 0.1; cell_fall : 0.1; rise_transition : 0.05; fall_transition : 0.05; } }
  }

  cell(NOR2) {
    area : 2;
    pin(A) { direction : input; capacitance : 0.001; }
    pin(B) { direction : input; capacitance : 0.001; }
    pin(Y) { direction : output; function : "!(A | B)"; timing() { cell_rise : 0.08; cell_fall : 0.08; rise_transition : 0.04; fall_transition : 0.04; } }
  }

  cell(INV) {
    area : 1;
    pin(A) { direction : input; capacitance : 0.001; }
    pin(Y) { direction : output; function : "!A"; timing() { cell_rise : 0.05; cell_fall : 0.05; rise_transition : 0.03; fall_transition : 0.03; } }
  }

  cell(XOR2) {
    area : 3;
    pin(A) { direction : input; capacitance : 0.0015; }
    pin(B) { direction : input; capacitance : 0.0015; }
    pin(Y) { direction : output; function : "A ^ B"; timing() { cell_rise : 0.12; cell_fall : 0.12; rise_transition : 0.06; fall_transition : 0.06; } }
  }

  cell(DFF) {
    area : 6;
    ff(IQ, IQN) { clocked_on : "CLK"; next_state : "D"; }
    pin(CLK) { direction : input; capacitance : 0.003; clock : true; }
    pin(RST_N) { direction : input; capacitance : 0.002; }
    pin(EN) { direction : input; capacitance : 0.002; }
    pin(D) { direction : input; capacitance : 0.002; }
    pin(Q) { direction : output; function : "IQ"; timing() { cell_rise : 0.15; cell_fall : 0.15; rise_transition : 0.08; fall_transition : 0.08; } }
  }
}
